files.tools/slowest_get.pl:
use strict; use warnings;
my ($max, $path) = (0, '');
for my $f (glob '请求/*.log') {
  open my $fh, '<', $f or die;
  while (<$fh>) {
    my @f = split;
    next unless $f[1] eq 'GET';
    if ($f[3] > $max) { $max = $f[3]; $path = $f[2]; }
  }
}
print "最慢的 GET 请求: $path\n";
